+package com.example.contact;
+
+import com.microsoft.playwright.Locator;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.web.server.LocalServerPort;
+import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;
+import org.vaadin.addons.dramafinder.element.ButtonElement;
+import org.vaadin.addons.dramafinder.element.EmailFieldElement;
+import org.vaadin.addons.dramafinder.element.GridElement;
+import org.vaadin.addons.dramafinder.element.TextAreaElement;
+import org.vaadin.addons.dramafinder.element.TextFieldElement;
+
+import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
+import static org.junit.jupiter.api.Assertions.assertEquals;
+
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class ContactViewBrowserTest extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port;
+    }
+
+    @Override
+    public String getView() {
+        return "/contact";
+    }
+
+    @Test
+    void headingLinkAndInitialFormState() {
+        assertEquals("Contact", page.locator("h1").innerText());
+
+        TextFieldElement name = TextFieldElement.getByLabel(page, "Name");
+        EmailFieldElement email = EmailFieldElement.getByLabel(page, "Email");
+        TextFieldElement phone = TextFieldElement.getByLabel(page, "Phone");
+        TextAreaElement message = TextAreaElement.getByLabel(page, "Message");
+
+        assertEquals("", name.getValue());
+        assertEquals("", email.getValue());
+        assertEquals("", phone.getValue());
+        assertEquals("", message.getValue());
+
+        ButtonElement send = ButtonElement.getByText(page, "Send");
+        send.assertEnabled();
+    }
+
+    @Test
+    void sendingValidMessageClearsFieldsAndShowsInGrid() {
+        TextFieldElement.getByLabel(page, "Name").setValue("Jane Doe");
+        TextFieldElement.getByLabel(page, "Phone").setValue("0400123123");
+        TextAreaElement.getByLabel(page, "Message").setValue("Hello from Playwright");
+
+        ButtonElement send = ButtonElement.getByText(page, "Send");
+        send.click();
+
+        assertThat(page.locator("vaadin-notification-card")).containsText("Message sent");
+
+        assertThat(TextFieldElement.getByLabel(page, "Name").getInputLocator()).hasValue("");
+        assertThat(TextFieldElement.getByLabel(page, "Phone").getInputLocator()).hasValue("");
+        assertThat(TextAreaElement.getByLabel(page, "Message").getInputLocator()).hasValue("");
+
+        send.assertDisabled();
+
+        TextFieldElement.getByLabel(page, "Name").setValue("x");
+        send.assertEnabled();
+
+        GridElement grid = GridElement.get(page);
+        grid.assertCellContent(0, 0, "Jane Doe");
+    }
+
+    @Test
+    void blankFormShowsValidationErrors() {
+        ButtonElement send = ButtonElement.getByText(page, "Send");
+        send.click();
+
+        TextFieldElement.getByLabel(page, "Name").assertInvalid();
+        TextFieldElement.getByLabel(page, "Name").assertErrorMessage("Name is required");
+
+        EmailFieldElement.getByLabel(page, "Email").assertInvalid();
+        EmailFieldElement.getByLabel(page, "Email").assertErrorMessage("Give an e-mail address or a phone number");
+
+        TextAreaElement.getByLabel(page, "Message").assertInvalid();
+        TextAreaElement.getByLabel(page, "Message").assertErrorMessage("Message is required");
+    }
+
+    @Test
+    void leavingWithUnsavedDataAsksFirst() {
+        TextFieldElement.getByLabel(page, "Name").setValue("Jane");
+
+        Locator aboutLink = page.getByText("About");
+        aboutLink.click();
+
+        Locator keepEditing = page.getByRole(com.microsoft.playwright.options.AriaRole.BUTTON,
+                new com.microsoft.playwright.Page.GetByRoleOptions().setName("Keep editing"));
+        assertThat(keepEditing).isVisible();
+        keepEditing.click();
+
+        assertThat(page.locator("h1")).hasText("Contact");
+        assertEquals("Jane", TextFieldElement.getByLabel(page, "Name").getValue());
+
+        aboutLink.click();
+        Locator discard = page.getByRole(com.microsoft.playwright.options.AriaRole.BUTTON,
+                new com.microsoft.playwright.Page.GetByRoleOptions().setName("Discard"));
+        assertThat(discard).isVisible();
+        discard.click();
+        assertThat(page.locator("h1")).hasText("About");
+    }
+
+    @Test
+    void leavingWithEmptyFormDoesNotAsk() {
+        Locator aboutLink = page.getByText("About");
+        aboutLink.click();
+        assertThat(page.locator("h1")).hasText("About");
+    }
+}
