+package com.example.contact;
+
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.RouterLink;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    @Test
+    void headingAndLinkPresent() {
+        ContactView view = navigate(ContactView.class);
+        H1 h1 = $(H1.class).first();
+        assertEquals("Contact", h1.getText());
+
+        RouterLink link = $(RouterLink.class).first();
+        assertEquals("About", link.getText());
+    }
+
+    @Test
+    void aboutViewHasHeading() {
+        AboutView view = navigate(AboutView.class);
+        H1 h1 = $(H1.class).first();
+        assertEquals("About", h1.getText());
+    }
+
+    @Test
+    void sendIsInitiallyEnabledAndFieldsEmpty() {
+        navigate(ContactView.class);
+        Button send = $(Button.class).first();
+        assertTrue(test(send).isUsable());
+
+        assertTrue($(TextField.class).withLabel("Name").first().isEmpty());
+        assertTrue($(EmailField.class).first().isEmpty());
+        assertTrue($(TextArea.class).first().isEmpty());
+    }
+
+    @Test
+    void blankFormFailsValidation() {
+        navigate(ContactView.class);
+        Button send = $(Button.class).first();
+        test(send).click();
+
+        TextField name = $(TextField.class).withLabel("Name").first();
+        EmailField email = $(EmailField.class).first();
+        TextArea message = $(TextArea.class).first();
+
+        assertTrue(name.isInvalid());
+        assertEquals("Name is required", name.getErrorMessage());
+        assertTrue(email.isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email.getErrorMessage());
+        assertTrue(message.isInvalid());
+        assertEquals("Message is required", message.getErrorMessage());
+
+        assertEquals(0, test($(Grid.class).<Grid<ContactMessage>>first()).size());
+    }
+
+    @Test
+    void invalidEmailIsRejected() {
+        navigate(ContactView.class);
+        TextField name = $(TextField.class).withLabel("Name").first();
+        EmailField email = $(EmailField.class).first();
+        TextArea message = $(TextArea.class).first();
+
+        test(name).setValue("Jane");
+        test(email).setValue("not-an-email");
+        test(message).setValue("Hello there");
+
+        Button send = $(Button.class).first();
+        test(send).click();
+
+        assertTrue(email.isInvalid());
+        assertEquals("Enter a valid e-mail address", email.getErrorMessage());
+    }
+
+    @Test
+    void messageTooLongIsRejected() {
+        navigate(ContactView.class);
+        TextField name = $(TextField.class).withLabel("Name").first();
+        TextField phone = $(TextField.class).withLabel("Phone").first();
+        TextArea message = $(TextArea.class).first();
+
+        test(name).setValue("Jane");
+        test(phone).setValue("12345");
+        test(message).setValue("a".repeat(501));
+
+        Button send = $(Button.class).first();
+        test(send).click();
+
+        assertTrue(message.isInvalid());
+        assertEquals("Message must be at most 500 characters", message.getErrorMessage());
+    }
+
+    @Test
+    void successfulSendClearsFormShowsNotificationAndDisablesSend() {
+        navigate(ContactView.class);
+        TextField name = $(TextField.class).withLabel("Name").first();
+        TextField phone = $(TextField.class).withLabel("Phone").first();
+        TextArea message = $(TextArea.class).first();
+
+        test(name).setValue("Jane");
+        test(phone).setValue("12345");
+        test(message).setValue("Hello there");
+
+        Button send = $(Button.class).first();
+        test(send).click();
+
+        Notification notification = $(Notification.class).first();
+        assertTrue(test(notification).getText().contains("Message sent"));
+
+        assertTrue(name.isEmpty());
+        assertTrue(phone.isEmpty());
+        assertTrue(message.isEmpty());
+
+        assertFalse(test(send).isUsable());
+
+        test(name).setValue("x");
+        assertTrue(test(send).isUsable());
+    }
+
+    @Test
+    void sentMessagesPersistAcrossViewRecreation() {
+        navigate(ContactView.class);
+        TextField name = $(TextField.class).withLabel("Name").first();
+        TextField phone = $(TextField.class).withLabel("Phone").first();
+        TextArea message = $(TextArea.class).first();
+
+        test(name).setValue("Jane");
+        test(phone).setValue("12345");
+        test(message).setValue("First message");
+        test($(Button.class).first()).click();
+
+        // simulate leaving and coming back
+        navigate(AboutView.class);
+        navigate(ContactView.class);
+
+        Grid<ContactMessage> grid = $(Grid.class).first();
+        assertEquals("Jane", test(grid).getRow(0).name());
+        assertEquals("First message", test(grid).getRow(0).message());
+    }
+
+    @Test
+    void leavingWithUnsavedInputShowsDialogAndKeepEditingCancelsNavigation() {
+        navigate(ContactView.class);
+        TextField name = $(TextField.class).withLabel("Name").first();
+        test(name).setValue("Jane");
+
+        RouterLink link = $(RouterLink.class).first();
+        test(link).navigate();
+
+        Dialog dialog = $(Dialog.class).first();
+        assertTrue(test(dialog).isUsable());
+
+        Button keepEditing = $(Button.class).withText("Keep editing").first();
+        test(keepEditing).click();
+
+        // still on contact view, dialog closed, field untouched
+        assertEquals("Jane", name.getValue());
+        assertFalse($(Dialog.class).exists());
+        H1 h1 = $(H1.class).first();
+        assertEquals("Contact", h1.getText());
+    }
+
+    @Test
+    void leavingWithUnsavedInputAndDiscardNavigatesAway() {
+        navigate(ContactView.class);
+        TextField name = $(TextField.class).withLabel("Name").first();
+        test(name).setValue("Jane");
+
+        RouterLink link = $(RouterLink.class).first();
+        test(link).navigate();
+
+        Button discard = $(Button.class).withText("Discard").first();
+        test(discard).click();
+
+        H1 h1 = $(H1.class).first();
+        assertEquals("About", h1.getText());
+    }
+
+    @Test
+    void leavingWithEmptyFormDoesNotShowDialog() {
+        navigate(ContactView.class);
+        RouterLink link = $(RouterLink.class).first();
+        test(link).navigate();
+
+        H1 h1 = $(H1.class).first();
+        assertEquals("About", h1.getText());
+    }
+}
